// ❌ OLD: renderToString waits for all createResource calls to finish.
// If a slow API takes 2 seconds, the user sees a blank white screen for 2s.
import { renderToString } from 'solid-js/web';
import App from './App';

app.get('*', async (req, res) => {
  const html = await renderToString(() => <App url={req.url} />);
  res.send(`<!DOCTYPE html><html><body>${html}</body></html>`);
});

// ✅ NEW: renderToStream emits the initial HTML shell immediately (instant TTFB)
// and pipes resolved Suspense chunks over the HTTP stream as they finish.
import { renderToStream } from 'solid-js/web';
import App from './App';

app.get('*', (req, res) => {
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  const { pipe } = renderToStream(() => <App url={req.url} />);
  pipe(res); // Streams chunks directly to client socket
});
